// ============================================================
//  🗺️ Lazy load نقشه (Leaflet) — کامپوننت فقط زمانی که کاربر
//  موقعیت تحویل را انتخاب می‌کند دانلود و اجرا می‌شود.
// ============================================================
const DeliveryLocationPicker = lazy(() => import(
  /* webpackChunkName: "delivery-picker" */
  '../components/DeliveryLocationPicker'
));

// ============================================================
//  ثابت‌ها
// ============================================================
const TOAST_DURATION = 2200;
const TOAST_VISIBLE_MS = 2500;

// ============================================================
//  🔑 کلیدهای ارتباط با QuickCalculator، OrderForm و MyDogs
//  این کلیدها باید با اون فایل‌ها یکی باشن.
//  بعد از ثبت موفق سبد، این فلگ‌ها هم پاک می‌شن تا اگه کاربر
//  به صفحه اصلی برگشت، OrderForm به‌اشتباه skip نکنه.
// ============================================================
const ORDER_SKIP_TO_FINAL_KEY = 'miko_order_skip_to_final';
const ORDER_SELECTED_DOG_KEY = 'miko_order_selected_dog_id';

// ============================================================
//  AddressModal
// ============================================================
function AddressModal({
  isOpen,
  onClose,
  onConfirm,
  loading,
  initialDelivery = null,
}) {
  const [delivery, setDelivery] = useState({
    city: '',
    address: '',
    lat: null,
    lng: null,
  });
  const closeButtonRef = useRef(null);
  const previousFocusRef = useRef(null);

  useEffect(() => {
    if (!isOpen) return undefined;
    previousFocusRef.current = document.activeElement;

    if (
      initialDelivery?.city &&
      initialDelivery?.address &&
      initialDelivery?.lat != null &&
      initialDelivery?.lng != null
    ) {
      setDelivery({
        city: initialDelivery.city,
        address: initialDelivery.address,
        lat: initialDelivery.lat,
        lng: initialDelivery.lng,
      });
    } else {
      setDelivery({ city: '', address: '', lat: null, lng: null });
    }

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    const focusTimer = window.setTimeout(
      () => closeButtonRef.current?.focus(),
      0
    );

    const handleKeyDown = (event) => {
      if (event.key === 'Escape' && !loading) onClose();
    };
    document.addEventListener('keydown', handleKeyDown);

    return () => {
      window.clearTimeout(focusTimer);
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = previousOverflow;
      if (previousFocusRef.current?.isConnected)
        previousFocusRef.current.focus();
    };
  }, [isOpen, initialDelivery, loading, onClose]);

  if (!isOpen) return null;

  const isValid = isDeliveryValid(delivery);
  const confirmLabel = 'تأیید آدرس و پرداخت';
  const loadingLabel = 'در حال ثبت سبد...';

  return (
    <div
      className="fixed inset-0 z-[60] flex items-end justify-center bg-ink-900/70 p-0 backdrop-blur-sm sm:items-center sm:p-4"
      onMouseDown={(e) => {
        if (e.target === e.currentTarget && !loading) onClose();
      }}
      role="presentation"
    >
      <div
        className="flex max-h-[95dvh] w-full flex-col overflow-hidden rounded-t-3xl border border-ink-200 bg-paper-50 shadow-editorial dark:border-dark-700 dark:bg-ink-800 sm:max-h-[90dvh] sm:max-w-2xl sm:rounded-3xl"
        dir="rtl"
        role="dialog"
        aria-modal="true"
        aria-labelledby="cart-address-modal-title"
      >
        <div
          className="mx-auto mt-2 h-1.5 w-12 shrink-0 rounded-full bg-ink-300 dark:bg-dark-600 sm:hidden"
          aria-hidden="true"
        />

        <header className="flex shrink-0 items-center gap-3 border-b border-ink-200 bg-brand-50/60 p-4 dark:border-dark-700 dark:bg-brand-500/10 sm:p-5">
          <div
            className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-brand-gradient p-2.5 text-white shadow-brand"
            aria-hidden="true"
          >
            <SiteImage
              imageKey="icon_location"
              fallback="📍"
              alt=""
              className="w-full h-full object-contain"
            />
          </div>

          <div className="min-w-0 flex-1">
            <h2
              id="cart-address-modal-title"
              className="font-display text-sm font-black text-ink-900 dark:text-cream-100 sm:text-base"
            >
              آدرس تحویل سبد
            </h2>
            <p className="mt-1 text-xs leading-6 text-ink-500 dark:text-cream-400">
              آدرس تحویل یک‌بار برای همه سفارش‌های این سبد ثبت می‌شود.
            </p>
          </div>

          <button
            ref={closeButtonRef}
            type="button"
            onClick={onClose}
            disabled={loading}
            className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl text-lg text-ink-500 transition hover:bg-rose-50 hover:text-rose-600 disabled:opacity-50 dark:hover:bg-rose-500/15"
            aria-label="بستن پنجره آدرس"
          >
            ✕
          </button>
        </header>

        <div className="min-h-0 flex-1 overflow-y-auto p-4 sm:p-5">
          <Suspense
            fallback={
              <div className="flex min-h-[160px] items-center justify-center text-sm text-ink-500">
                در حال بارگذاری نقشه…
              </div>
            }
          >
            <DeliveryLocationPicker
              value={delivery}
              onChange={setDelivery}
              disabled={loading}
            />
          </Suspense>
        </div>

        <footer className="flex shrink-0 flex-col-reverse gap-2.5 border-t border-ink-200 bg-paper-100/70 p-4 dark:border-dark-700 dark:bg-ink-900/50 sm:flex-row sm:p-5">
          <button
            type="button"
            onClick={onClose}
            disabled={loading}
            className="min-h-12 w-full rounded-xl border border-ink-200 bg-paper-50 px-5 py-3 text-sm font-bold text-ink-700 transition hover:bg-paper-100 disabled:opacity-50 dark:border-dark-600 dark:bg-ink-700 dark:text-cream-200 sm:w-auto"
          >
            انصراف
          </button>

          <button
            type="button"
            onClick={() => onConfirm(delivery)}
            disabled={!isValid || loading}
            className={`flex min-h-12 w-full items-center justify-center gap-2 rounded-xl px-6 py-3 text-sm font-black transition sm:flex-1 ${
              !isValid || loading
                ? 'cursor-not-allowed bg-paper-200 text-ink-400 shadow-none dark:bg-ink-700 dark:text-cream-500'
                : 'bg-brand-gradient text-white shadow-brand hover:opacity-95 active:opacity-90'
            }`}
          >
            {loading ? (
              <>
                <span
                  className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent"
                  aria-hidden="true"
                />
                <span>{loadingLabel}</span>
              </>
            ) : (
              <>
                <span className="w-4 h-4" aria-hidden="true">
                  <SiteImage
                    imageKey="icon_check"
                    fallback="✓"
                    alt=""
                    className="w-full h-full object-contain"
                  />
                </span>
                <span>{confirmLabel}</span>
              </>
            )}
          </button>
        </footer>
      </div>
    </div>
  );
}

