// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function Cart({ embedded = false }) {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const cart = useCart();

  const [showAddressModal, setShowAddressModal] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [lastDelivery, setLastDelivery] = useState(null);
  const [submittedBatchId, setSubmittedBatchId] = useState(null);
  const [orderSubmitted, setOrderSubmitted] = useState(false);

  // ✅ reactive isGuest
  const [isGuest, setIsGuest] = useState(() => {
    try {
      return !localStorage.getItem(STORAGE_KEYS.USER_TOKEN);
    } catch {
      return true;
    }
  });

  const isMountedRef = useRef(false);
  const submissionRequestRef = useRef(false);
  const redirectTimerRef = useRef(null);
  const welcomeShownRef = useRef(false);
  const pendingOrderPickedRef = useRef(false);

  const fromRegister = searchParams.get('from') === 'register';
  const fromLogin = searchParams.get('from') === 'login';

  // ─── mount lifecycle ─────────────────────────────────────
  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
      if (redirectTimerRef.current)
        window.clearTimeout(redirectTimerRef.current);
    };
  }, []);

  // ─── sync auth state (reactive isGuest) ──────────────────
  useEffect(() => {
    const checkAuth = () => {
      try {
        setIsGuest(!localStorage.getItem(STORAGE_KEYS.USER_TOKEN));
      } catch {
        setIsGuest(true);
      }
    };
    checkAuth();
    window.addEventListener('storage', checkAuth);
    window.addEventListener(AUTH_EVENT, checkAuth);
    return () => {
      window.removeEventListener('storage', checkAuth);
      window.removeEventListener(AUTH_EVENT, checkAuth);
    };
  }, []);

  // ─── load lastDeliveryAddress ───────────────────────────
  useEffect(() => {
    try {
      const raw = sessionStorage.getItem(SESSION_KEYS.LAST_DELIVERY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed?.city && parsed?.address) setLastDelivery(parsed);
      }
    } catch {
      /* ignore */
    }
  }, []);

  // ─── ✅ Fallback: pick up pendingOrder → add to cart ──────
  useEffect(() => {
    if (pendingOrderPickedRef.current) return;
    pendingOrderPickedRef.current = true;

    let raw = null;
    try {
      raw = sessionStorage.getItem(SESSION_KEYS.PENDING_ORDER);
    } catch {
      return;
    }
    if (!raw) return;

    let pendingOrder = null;
    try {
      pendingOrder = JSON.parse(raw);
    } catch {
      return;
    }
    if (!pendingOrder || typeof pendingOrder !== 'object') return;

    let orderForCart = null;

    if (pendingOrder.form && typeof pendingOrder.form === 'object') {
      orderForCart = {
        form: pendingOrder.form,
        summary: pendingOrder.summary || {},
      };
    } else if (pendingOrder.dog_id && pendingOrder.dog_name) {
      let summary = {};
      try {
        const rawResult = sessionStorage.getItem(SESSION_KEYS.QUICK_RESULT);
        if (rawResult) summary = JSON.parse(rawResult) || {};
      } catch {
        /* ignore */
      }
      orderForCart = {
        form: pendingOrder,
        summary,
      };
    }

    if (!orderForCart) return;

    const result = addPendingOrderToCart(orderForCart);

    if (result.ok) {
      try {
        sessionStorage.removeItem(SESSION_KEYS.PENDING_ORDER);
        sessionStorage.removeItem(SESSION_KEYS.PENDING_DOG);
      } catch {
        /* ignore */
      }
      toast.success('سفارش شما به سبد خرید اضافه شد.', {
        duration: TOAST_DURATION,
      });
    } else if (result.reason === 'duplicate') {
      try {
        sessionStorage.removeItem(SESSION_KEYS.PENDING_ORDER);
        sessionStorage.removeItem(SESSION_KEYS.PENDING_DOG);
      } catch {
        /* ignore */
      }
      toast.info('این سفارش قبلاً به سبد اضافه شده بود.', {
        duration: TOAST_DURATION,
      });
    } else if (result.reason === 'limit') {
      toast.error(
        `سبد خرید پر است (حداکثر ${result.max} سفارش). ابتدا یک سفارش را حذف کنید.`,
        { duration: 5000 }
      );
    }
  }, []);

  // ─── welcome toast after register/login redirect ────────
  useEffect(() => {
    if (welcomeShownRef.current) return;
    if (!fromRegister && !fromLogin) return;
    if (cart.totalCount === 0) return;
    welcomeShownRef.current = true;
    toast.success('خوش آمدید! سفارش‌های شما در سبد آماده‌ی پرداخت است.', {
      duration: TOAST_DURATION,
    });
  }, [fromRegister, fromLogin, cart.totalCount]);

  // ─── remove item ────────────────────────────────────────
  const handleRemove = useCallback(
    (localId) => {
      if (submitting) return;
      if (!window.confirm('این سفارش را از سبد حذف کنیم؟')) return;
      cart.removeItem(localId);
      toast.success('از سبد حذف شد.');
    },
    [cart, submitting]
  );

  // ============================================================
  //  ✅ FIX v6: checkout entry point
  //  - مهمان‌ها مستقیم به لاگین می‌رن — بدون پرسیدن آدرس
  //  - آدرس فقط بعد از لاگین، در همین صفحه Cart گرفته می‌شه
  //  - سبد در localStorage ذخیره شده و در طول فرآیند لاگین حفظ می‌شه
  // ============================================================
  const handleCheckout = useCallback(() => {
    if (cart.totalCount === 0 || submitting) return;

    // ─── مسیر مهمان: مستقیم به لاگین ───
    if (isGuest) {
      // فقط marker برای نمایش شمارش سبد در صفحه لاگین
      // توجه: delivery داده‌ها اینجا ذخیره نمی‌شن — فقط بعد از لاگین گرفته می‌شن
      try {
        const orders = cart.items.map((it) => it.formPayload);
        sessionStorage.setItem(
          SESSION_KEYS.PENDING_CART,
          JSON.stringify({ orders, delivery: null })
        );
      } catch {
        /* ignore */
      }

      toast.info(
        'برای تکمیل سفارش، لطفاً وارد شوید یا ثبت‌نام کنید.',
        { duration: TOAST_DURATION }
      );

      redirectTimerRef.current = window.setTimeout(() => {
        if (isMountedRef.current) navigate('/login?next=cart');
      }, TOAST_VISIBLE_MS);
      return;
    }

    // ─── مسیر کاربر لاگین‌شده: باز کردن مودال آدرس ───
    setShowAddressModal(true);
  }, [cart.totalCount, cart.items, submitting, isGuest, navigate]);

  // ============================================================
  //  Confirmation + batch submit
  //  ✅ FIX v6: مسیر مهمان حذف شد — این تابع فقط برای کاربر
  //             لاگین‌شده اجرا می‌شه. شاخه 401 برای انقضای توکن
  //             در حین submit نگه داشته شده.
  //  ✅ FIX v7: منطق تطبیق سگ بر اساس نام قبل از submit
  //             - اگه dog_id معتبره (به کاربر تعلق داره) → حفظ
  //             - اگه dog_id نامعتبره یا خالی → چک کن سگی با همین نام هست؟
  //               - آره → dog_id اون سگ رو set کن (جلوگیری از سگ تکراری)
  //               - نه → dog_id رو خالی بذار تا backend سگ جدید بسازه
  //             این طوری وقتی کاربر مهمان سفارش می‌ده و بعد لاگین
  //             می‌کنه، اگه قبلاً سگی با همون نام ثبت کرده باشه، سفارش
  //             به همون وصل می‌شه وگرنه سگ جدید ساخته می‌شه.
  // ============================================================
  const handleAddressConfirm = async (deliveryData) => {
    if (submissionRequestRef.current) return;
    if (cart.totalCount === 0) return;

    submissionRequestRef.current = true;
    setSubmitting(true);

    let navigatingAway = false;
    let payload = null;

    try {
      // ✅ FIX v7: دریافت لیست سگ‌های کاربر برای تطبیق dog_id
      let userDogIds = new Set();
      let userDogsByName = new Map(); // dog_name (trimmed lowercase) → dog_id

      try {
        const dogsRes = await userAxios.get('/api/dogs');
        if (Array.isArray(dogsRes.data)) {
          for (const dog of dogsRes.data) {
            const did = Number(dog.id);
            if (!Number.isNaN(did)) {
              userDogIds.add(did);
            }
            // نقشه نام → id (case-insensitive, trimmed)
            const name = (dog.name || dog.dog_name || '').toString().trim().toLowerCase();
            if (name && !userDogsByName.has(name)) {
              userDogsByName.set(name, did);
            }
          }
        }
      } catch (err) {
        // اگه دریافت لیست سگ‌ها ناموفق بود، نمی‌تونیم تطبیق کنیم
        // → ریسک: ممکنه dog_id نامعتبر باشه یا سگ تکراری ساخته بشه
        console.warn('خطا در دریافت لیست سگ‌ها برای تطبیق dog_id:', err);
      }

      const orders = cart.items.map((it) => {
        const formPayload = { ...it.formPayload };
        const dogName = (formPayload.dog_name || '').toString().trim();
        const dogNameKey = dogName.toLowerCase();

        // ─── مرحله ۱: اعتبارسنجی dog_id موجود ───
        if (formPayload.dog_id != null && formPayload.dog_id !== '') {
          const dogIdNum = Number(formPayload.dog_id);
          if (userDogIds.has(dogIdNum)) {
            // ✅ dog_id معتبره → حفظش کن
            return {
              ...formPayload,
              delivery_lat: deliveryData.lat,
              delivery_lng: deliveryData.lng,
              delivery_address: deliveryData.address,
              delivery_city: deliveryData.city,
            };
          }
          // ❌ dog_id نامعتبره (به کاربر تعلق نداره) → حذفش کن
          console.warn(
            `dog_id=${formPayload.dog_id} به کاربر تعلق نداره — حذف شد.`
          );
          delete formPayload.dog_id;
        }

        // ─── مرحله ۲: تطبیق بر اساس نام ───
        // اگه سگی با همین نام از قبل در «سگ‌های من» باشه → ازش استفاده کن
        if (dogNameKey && userDogsByName.has(dogNameKey)) {
          const matchedDogId = userDogsByName.get(dogNameKey);
          console.info(
            `سگ با نام «${dogName}» از قبل موجود است → dog_id=${matchedDogId} متصل شد.`
          );
          formPayload.dog_id = matchedDogId;
        }
        // در غیر اینصورت → dog_id خالی می‌مونه و backend در
        // _create_dog_from_order سگ جدید می‌سازه و به «سگ‌های من» اضافه می‌کنه

        return {
          ...formPayload,
          delivery_lat: deliveryData.lat,
          delivery_lng: deliveryData.lng,
          delivery_address: deliveryData.address,
          delivery_city: deliveryData.city,
        };
      });

      payload = {
        orders,
        delivery: {
          delivery_lat: deliveryData.lat,
          delivery_lng: deliveryData.lng,
          delivery_address: deliveryData.address,
          delivery_city: deliveryData.city,
        },
      };

      // ─── ثبت سبد کاربر لاگین‌شده ───
      const res = await userAxios.post('/api/submit-orders', payload);

      if (!isMountedRef.current) return;

      const batchId = res.data.batch_id;

      try {
        sessionStorage.setItem(
          SESSION_KEYS.LAST_DELIVERY,
          JSON.stringify({
            city: deliveryData.city,
            address: deliveryData.address,
            lat: deliveryData.lat,
            lng: deliveryData.lng,
          })
        );
      } catch {
        /* ignore */
      }

      setLastDelivery(deliveryData);
      cart.clearCart();

      // ✅ FIX: پاک‌سازی همهٔ pendingهای مرتبط
      // تا login/register بعدی سعی نکند دوباره ثبت کند
      try {
        sessionStorage.removeItem(SESSION_KEYS.PENDING_ORDER);
        sessionStorage.removeItem(SESSION_KEYS.PENDING_DOG);
        sessionStorage.removeItem(SESSION_KEYS.PENDING_CART);
        sessionStorage.removeItem(SESSION_KEYS.QUICK_FORM);
        sessionStorage.removeItem(SESSION_KEYS.QUICK_RESULT);
        // ✅ FIX v7: پاک‌سازی فلگ‌های skip_to_final و selected_dog_id
        // تا بعد از ثبت موفق سبد، اگه کاربر به صفحه اصلی برگشت،
        // OrderForm به‌اشتباه skip نکنه به مرحله آخر با سگ قدیمی
        sessionStorage.removeItem(ORDER_SKIP_TO_FINAL_KEY);
        sessionStorage.removeItem(ORDER_SELECTED_DOG_KEY);
      } catch {
        /* ignore */
      }

      setShowAddressModal(false);
      setSubmittedBatchId(batchId);
      setOrderSubmitted(true);

      navigatingAway = true;
      redirectTimerRef.current = window.setTimeout(() => {
        if (isMountedRef.current) {
          navigate(`/panel/payment/batch/${batchId}`, { replace: true });
        }
      }, TOAST_VISIBLE_MS);
    } catch (err) {
      if (!isMountedRef.current) return;

      // ✅ شاخه 401: توکن در حین submit منقضی شده
      // آدرس وارد شده رو در LAST_DELIVERY ذخیره می‌کنیم تا بعد از لاگین
      // در مودال به‌صورت pre-fill نمایش داده بشه
      if (err.response?.status === 401 && payload) {
        try {
          sessionStorage.setItem(
            SESSION_KEYS.LAST_DELIVERY,
            JSON.stringify({
              city: deliveryData.city,
              address: deliveryData.address,
              lat: deliveryData.lat,
              lng: deliveryData.lng,
            })
          );
        } catch {
          /* ignore */
        }

        setShowAddressModal(false);
        toast.error(
          'نشست شما منقضی شده است. سبد شما حفظ شد — لطفاً دوباره وارد شوید.',
          { duration: TOAST_DURATION }
        );

        navigatingAway = true;
        redirectTimerRef.current = window.setTimeout(() => {
          if (isMountedRef.current) navigate('/login?next=cart');
        }, TOAST_VISIBLE_MS);
        return;
      }

      toast.error(
        'خطا در ثبت سبد: ' +
          (err.response?.data?.detail || err.message)
      );
    } finally {
      if (!navigatingAway) {
        submissionRequestRef.current = false;
        if (isMountedRef.current) setSubmitting(false);
      }
    }
  };

  // ============================================================
  //  ✅ embedded mode: وقتی داخل پنل کاربر رندر می‌شه،
  //  SiteHeader/SiteFooter/ToastHost حذف می‌شن چون پنل
  //  خودش هدر، فوتر و ToastHost داره. همچنین min-h-screen
  //  حذف می‌شه تا داخل اسکرول‌کانتینر پنل درست بنشه.
  // ============================================================
  const pageWrapperClass = embedded
    ? 'flex flex-col bg-paper-100 text-ink-900 dark:bg-ink-900 dark:text-cream-100'
    : 'flex min-h-screen flex-col bg-paper-100 text-ink-900 dark:bg-ink-900 dark:text-cream-100';

  // ============================================================
  //  Render: empty cart
  // ============================================================
  if (cart.totalCount === 0 && !orderSubmitted) {
    return (
      <div
        dir="rtl"
        className={pageWrapperClass}
      >
        {!embedded && <ToastHost />}
        {!embedded && <SiteHeader />}

        <main className="flex-1">
          <div className="mx-auto max-w-3xl px-4 py-16 text-center sm:px-6 sm:py-24">
            <div className="mx-auto mb-6 flex h-24 w-24 items-center justify-center rounded-3xl bg-brand-100 dark:bg-brand-500/15">
              <SiteImage
                imageKey="icon_cart"
                showPlaceholder
                placeholderContent={
                  <span className="text-5xl" aria-hidden="true">
                    🛒
                  </span>
                }
                className="w-12 h-12 object-contain"
              />
            </div>
            <h1 className="font-display text-2xl font-black text-ink-900 dark:text-cream-100 sm:text-3xl">
              سبد خریدت خالیه
            </h1>
            <p className="mt-3 text-sm leading-7 text-ink-500 dark:text-cream-400 sm:text-base">
              هنوز سفارشی به سبد اضافه نکردی. از صفحه اصلی اطلاعات سگت رو
              وارد کن و با دکمه «افزودن به سبد خرید» سفارش رو اضافه کن.
            </p>

            <div className="mt-8 flex flex-col items-center gap-3 sm:flex-row sm:justify-center">
              <Link
                to="/"
                className="inline-flex min-h-12 w-full items-center justify-center gap-2 rounded-xl bg-brand-700 px-6 text-sm font-extrabold text-white transition hover:bg-brand-800 dark:bg-brand-500 dark:text-ink-950 dark:hover:bg-brand-400 sm:w-auto"
              >
                شروع محاسبه
                <SiteImage
                  imageKey="icon_arrow_left"
                  fallback="←"
                  alt=""
                  className="leading-none inline-flex"
                />
              </Link>

              {!isGuest && (
                <Link
                  to="/panel/orders"
                  className="inline-flex min-h-12 w-full items-center justify-center gap-2 rounded-xl border border-ink-200 bg-paper-50 px-6 text-sm font-bold text-ink-700 transition hover:bg-paper-100 dark:border-dark-600 dark:bg-ink-800 dark:text-cream-200 dark:hover:bg-ink-700 sm:w-auto"
                >
                  مشاهده سفارش‌های من
                </Link>
              )}
            </div>
          </div>
        </main>

        {!embedded && <SiteFooter />}
      </div>
    );
  }

  // ============================================================
  //  Render: success
  // ============================================================
  if (orderSubmitted && submittedBatchId) {
    return (
      <div
        dir="rtl"
        className={pageWrapperClass}
      >
        {!embedded && <ToastHost />}
        {!embedded && <SiteHeader />}

        <main className="flex-1">
          <div className="mx-auto max-w-2xl px-4 py-12 sm:px-6 sm:py-16">
            <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-accent-600 via-accent-600 to-accent-700 p-8 text-white sm:p-10">
              <div
                aria-hidden="true"
                className="pointer-events-none absolute -left-16 -top-16 h-48 w-48 rounded-full bg-white/[0.08]"
              />

              <div className="relative text-center">
                <div className="mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-full border border-white/25 bg-white/15 p-4 sm:h-20 sm:w-20">
                  <SiteImage
                    imageKey="icon_check"
                    fallback="✓"
                    alt=""
                    className="w-full h-full object-contain brightness-0 invert"
                  />
                </div>

                <h1 className="font-display text-2xl font-black sm:text-3xl">
                  سبد خرید ثبت شد!
                </h1>

                <p className="mt-3 text-sm leading-7 text-white/80">
                  همه سفارش‌های سبد شما با موفقیت ثبت شدند. برای تکمیل، فیش
                  پرداخت را آپلود کنید.
                </p>

                <div className="mt-5 inline-flex flex-wrap items-center justify-center gap-3 rounded-xl border border-white/20 bg-white/10 px-4 py-3">
                  <span className="text-sm text-white/80">شناسه سبد</span>
                  <strong className="font-mono text-xs sm:text-sm">
                    {submittedBatchId.slice(0, 12)}...
                  </strong>
                </div>

                <p className="mt-4 text-xs text-white/75">
                  در حال انتقال به صفحه پرداخت...
                </p>

                <button
                  type="button"
                  onClick={() =>
                    navigate(`/panel/payment/batch/${submittedBatchId}`)
                  }
                  className="mt-6 inline-flex min-h-12 w-full items-center justify-center gap-2 rounded-xl bg-white px-6 text-sm font-black text-accent-700 transition hover:bg-cream-50 sm:w-auto"
                >
                  رفتن به صفحه پرداخت
                  <SiteImage
                    imageKey="icon_arrow_left"
                    fallback="←"
                    alt=""
                    className="leading-none inline-flex"
                  />
                </button>
              </div>
            </div>
          </div>
        </main>

        {!embedded && <SiteFooter />}
      </div>
    );
  }

  // ============================================================
  //  Render: cart items
  // ============================================================
  return (
    <div
      dir="rtl"
      className={pageWrapperClass}
    >
      {!embedded && <ToastHost />}
      {!embedded && <SiteHeader />}

      <main className="flex-1">
        <div className="mx-auto max-w-6xl px-4 py-8 sm:px-6 sm:py-12 lg:px-8">
          {(fromRegister || fromLogin) && cart.totalCount > 0 && (
            <div className="mb-5 flex items-start gap-3 rounded-2xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-900 dark:border-emerald-700/50 dark:bg-emerald-500/10 dark:text-emerald-200">
              <span className="text-lg leading-none" aria-hidden="true">
                ✅
              </span>
              <div className="flex-1">
                <p className="font-black">
                  {fromRegister
                    ? 'خوش آمدید! حالا می‌تونید سفارش‌تون رو تکمیل کنید.'
                    : 'خوش برگشتی! حالا می‌تونید سفارش‌تون رو تکمیل کنید.'}
                </p>
                <p className="mt-1 text-xs leading-6 opacity-90">
                  برای ادامه، روی «ادامه و انتخاب آدرس» بزنید و آدرس تحویل رو
                  وارد کنید. اگر می‌خواهی برای سگ دیگری هم سفارش ثبت کنی، از
                  صفحه اصلی سگ جدید اضافه کن.
                </p>
              </div>
            </div>
          )}

          <div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
            <div>
              <h1 className="font-display text-2xl font-black leading-tight text-ink-900 dark:text-cream-100 sm:text-3xl">
                سبد خرید
              </h1>
              <p className="mt-1.5 text-sm text-ink-500 dark:text-cream-400">
                {toFa(cart.totalCount)} سفارش آماده‌ی پرداخت
              </p>
            </div>
            <Link
              to="/"
              className="text-sm font-bold text-brand-700 hover:text-brand-800 dark:text-brand-300 dark:hover:text-brand-200"
            >
              + افزودن سگ دیگر
            </Link>
          </div>

          <div className="grid grid-cols-1 gap-6 lg:grid-cols-[minmax(0,1fr)_360px]">
            <div className="space-y-3">
              {cart.items.map((item) => (
                <CartItemCard
                  key={item.localId}
                  item={item}
                  onRemove={handleRemove}
                  disabled={submitting}
                />
              ))}
            </div>

            <aside className="lg:sticky lg:top-28 lg:self-start">
              <div className="rounded-2xl border border-ink-200 bg-white p-5 shadow-sm dark:border-dark-700 dark:bg-ink-800">
                <h2 className="text-base font-black text-ink-900 dark:text-white">
                  خلاصه پرداخت
                </h2>

                <dl className="mt-4 space-y-2 text-sm">
                  <div className="flex items-center justify-between">
                    <dt className="text-ink-500 dark:text-ink-400">
                      تعداد سفارش
                    </dt>
                    <dd className="font-bold text-ink-900 dark:text-white">
                      {toFa(cart.totalCount)}
                    </dd>
                  </div>
                  <div className="flex items-center justify-between">
                    <dt className="text-ink-500 dark:text-ink-400">
                      جمع جزء
                    </dt>
                    <dd className="font-bold tabular-nums text-ink-900 dark:text-white">
                      {toFa(cart.totalAmount)} تومان
                    </dd>
                  </div>
                  <div className="flex items-center justify-between">
                    <dt className="text-ink-500 dark:text-ink-400">
                      هزینه ارسال
                    </dt>
                    <dd className="text-xs font-bold text-ink-500 dark:text-ink-400">
                      پس از تأیید آدرس
                    </dd>
                  </div>

                  <div className="mt-4 flex items-center justify-between border-t border-ink-100 pt-4 dark:border-dark-700">
                    <dt className="text-sm font-black text-ink-900 dark:text-white">
                      مبلغ قابل پرداخت
                    </dt>
                    <dd className="text-xl font-black tabular-nums text-brand-700 dark:text-brand-300">
                      {toFa(cart.totalAmount)}{' '}
                      <span className="text-xs font-semibold text-ink-500 dark:text-ink-400">
                        تومان
                      </span>
                    </dd>
                  </div>
                </dl>

                <button
                  type="button"
                  onClick={handleCheckout}
                  disabled={submitting}
                  className="mt-5 inline-flex min-h-12 w-full items-center justify-center gap-2 rounded-xl bg-brand-700 px-6 text-sm font-extrabold text-white transition hover:bg-brand-800 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500/40 disabled:cursor-not-allowed disabled:opacity-60 dark:bg-brand-500 dark:text-ink-950 dark:hover:bg-brand-400"
                >
                  {isGuest ? (
                    <>
                      <SiteImage
                        imageKey="icon_lock"
                        fallback="🔐"
                        alt=""
                        className="leading-none inline-flex"
                      />
                      ورود / ثبت‌نام و پرداخت
                    </>
                  ) : (
                    <>
                      ادامه و انتخاب آدرس
                      <SiteImage
                        imageKey="icon_arrow_left"
                        fallback="←"
                        alt=""
                        className="leading-none inline-flex"
                      />
                    </>
                  )}
                </button>

                <p className="mt-3 text-center text-[11px] leading-5 text-ink-400 dark:text-ink-500">
                  با تأیید، یک فیش واحد برای همه سفارش‌های این سبد ثبت می‌شود.
                </p>
              </div>
            </aside>
          </div>
        </div>
      </main>

      {!embedded && <SiteFooter />}

      <AddressModal
        isOpen={showAddressModal}
        onClose={() => !submitting && setShowAddressModal(false)}
        onConfirm={handleAddressConfirm}
        loading={submitting}
        initialDelivery={lastDelivery}
      />
    </div>
  );
}
